/*! chromokit 0.2.0 · MIT · https://github.com/js2264/chromokit · generated by scripts/build.mjs — do not edit; put local changes in your own stylesheet */
/*
 * chromokit theme: light, dark, or the system's.
 *
 * Load it in <head>, without `defer`, so the stored choice is on <html>
 * before the first paint and a dark-mode reader never sees a white flash:
 *
 *     <script src="chromokit/theme.js"><\/script>
 *
 * "System" is the absence of an override, not a third palette: the stylesheet
 * already answers `prefers-color-scheme`, so the script writes
 * `data-theme="light" | "dark"` on <html> for an explicit choice and removes
 * it for the system's. It also writes `data-cx-theme` (always set, including
 * "system") for the toggle's icon, and mirrors the choice to `data-bs-theme`
 * when the page is a Bootstrap one that already carries that attribute.
 *
 * Any element with `data-cx-theme-toggle` cycles system → dark → light (or
 * system → light → dark on a dark machine, so the first press always changes
 * what is on screen). The choice lives in localStorage under
 * `<html data-cx-theme-key="…">`, by default "chromokit:theme".
 */
;(() => {
  if (window.chromokitTheme) return
  const root = document.documentElement
  const KEY = root.getAttribute('data-cx-theme-key') || 'chromokit:theme'
  const media = window.matchMedia ? window.matchMedia('(prefers-color-scheme: dark)') : null

  const read = () => {
    try {
      const value = window.localStorage.getItem(KEY)
      return value === 'light' || value === 'dark' ? value : 'system'
    } catch {
      return 'system'
    }
  }

  const resolved = (choice) => (choice === 'system' ? (media && media.matches ? 'dark' : 'light') : choice)

  const apply = (choice) => {
    root.setAttribute('data-cx-theme', choice)
    if (choice === 'system') root.removeAttribute('data-theme')
    else root.setAttribute('data-theme', choice)
    if (root.hasAttribute('data-bs-theme')) root.setAttribute('data-bs-theme', resolved(choice))
    for (const button of document.querySelectorAll('[data-cx-theme-toggle]')) {
      const label = `Theme: ${choice}${choice === 'system' ? ` (${resolved(choice)})` : ''}`
      button.setAttribute('title', label)
      button.setAttribute('aria-label', label)
    }
  }

  const set = (choice) => {
    try {
      if (choice === 'system') window.localStorage.removeItem(KEY)
      else window.localStorage.setItem(KEY, choice)
    } catch {
      /* private mode: the choice lasts for this page only */
    }
    apply(choice)
  }

  const next = () => {
    const current = read()
    const order = media && media.matches ? ['system', 'light', 'dark'] : ['system', 'dark', 'light']
    return order[(order.indexOf(current) + 1) % order.length]
  }

  apply(read())
  if (media && media.addEventListener) media.addEventListener('change', () => apply(read()))

  document.addEventListener('click', (event) => {
    const button = event.target instanceof Element ? event.target.closest('[data-cx-theme-toggle]') : null
    if (button) set(next())
  })
  document.addEventListener('DOMContentLoaded', () => apply(read()))

  window.chromokitTheme = { get: read, set, resolved: () => resolved(read()) }
})()

/*
 * The page of a report (the report kit): what it does once loaded.
 *
 * - Plots: plotly.js, which the page loads from its CDN, draws every
 *   `[data-figure]` from the figures in `#cx-report-figures`. The page paints
 *   each plot's chrome (background, text, axes, grid, legend, hover labels)
 *   in its palette, and paints it again when the palette changes; a trace's
 *   own colours stay, and a trace without one takes the palette's series.
 *   Without plotly.js (offline), each plot says so, and the numbers and
 *   tables stay.
 * - Tables `[data-sortable]`: sorted on a click on a header (a cell's
 *   `data-sort`, or its text), filtered as you type in their
 *   `.cx-report__filter`, downloaded as CSV (the rows shown) by their
 *   `.cx-report__download`.
 * - A card `[data-filter-table]` shows the rows of its table whose
 *   `data-filter-value` is its own; a second click shows them all again.
 * - The bar marks the section being read.
 *
 * Loaded in <head> after theme.js, which sets the palette before the first
 * paint; everything else waits for the page.
 */
;(() => {
  if (window.__chromokitReport) return
  window.__chromokitReport = true

  const ready = (fn) => (document.readyState === 'loading' ? document.addEventListener('DOMContentLoaded', fn) : fn())

  // ---- plots ---------------------------------------------------------------

  const token = (name) => getComputedStyle(document.documentElement).getPropertyValue(name).trim()

  /** A colour of the palette (#rrggbb), see-through: for the minor grid. */
  const faded = (hex, alpha) => {
    const m = /^#([0-9a-f]{2})([0-9a-f]{2})([0-9a-f]{2})/i.exec(hex)
    return m ? `rgba(${parseInt(m[1], 16)}, ${parseInt(m[2], 16)}, ${parseInt(m[3], 16)}, ${alpha})` : hex
  }

  const CARTESIAN = /^(scatter|scattergl|bar|histogram|histogram2d|histogram2dcontour|box|violin|heatmap|heatmapgl|contour|waterfall|funnel|candlestick|ohlc|image)$/

  /** A figure in the page's palette: its chrome repainted, its data's colours kept. */
  function styled(figure) {
    const palette = {
      text: token('--cx-text'),
      dim: token('--cx-text-dim'),
      border: token('--cx-border'),
      strong: token('--cx-border-strong'),
      raised: token('--cx-bg-raised'),
      sans: token('--cx-sans'),
      series: [1, 2, 3, 4, 5, 6, 7].map((n) => token(`--cx-series-${n}`)).filter(Boolean),
    }
    const layout = structuredClone(figure.layout || {})
    const data = structuredClone(figure.data || [])
    const font = (value, color) => ({ ...(value || {}), color })
    const titled = (title, color) => {
      if (title === undefined || title === null) return title
      const object = typeof title === 'object' ? { ...title } : { text: String(title) }
      object.font = font(object.font, color)
      return object
    }

    layout.font = { ...(layout.font || {}), family: palette.sans, color: palette.text }
    layout.paper_bgcolor = 'rgba(0,0,0,0)'
    layout.plot_bgcolor = 'rgba(0,0,0,0)'
    if (!layout.colorway && palette.series.length > 0) layout.colorway = palette.series
    if (layout.title !== undefined) layout.title = titled(layout.title, palette.text)
    layout.legend = { ...(layout.legend || {}), bgcolor: 'rgba(0,0,0,0)', font: font(layout.legend?.font, palette.dim) }
    layout.hoverlabel = {
      ...(layout.hoverlabel || {}),
      bgcolor: palette.raised,
      bordercolor: palette.strong,
      font: font(layout.hoverlabel?.font, palette.text),
    }

    const axes = new Set(Object.keys(layout).filter((key) => /^[xy]axis\d*$/.test(key)))
    if (data.some((trace) => CARTESIAN.test(trace.type || 'scatter'))) {
      axes.add('xaxis')
      axes.add('yaxis')
    }
    for (const key of axes) {
      const axis = { ...(layout[key] || {}) }
      Object.assign(axis, { gridcolor: palette.border, linecolor: palette.strong, zerolinecolor: palette.border, tickcolor: palette.strong })
      axis.tickfont = font(axis.tickfont, palette.dim)
      if (axis.title !== undefined) axis.title = titled(axis.title, palette.dim)
      if (axis.minor) axis.minor = { ...axis.minor, gridcolor: faded(palette.border, 0.45), tickcolor: palette.strong }
      layout[key] = axis
    }

    for (const trace of data) {
      if (trace.colorbar || /heatmap|contour|histogram2d/.test(trace.type || '')) {
        trace.colorbar = {
          ...(trace.colorbar || {}),
          outlinewidth: 0,
          tickfont: font(trace.colorbar?.tickfont, palette.dim),
          title: titled(trace.colorbar?.title ?? '', palette.dim),
        }
      }
      if (trace.type === 'sankey') {
        trace.textfont = font(trace.textfont, palette.text)
        trace.node = { ...(trace.node || {}), line: { ...(trace.node?.line || {}), color: palette.border } }
      }
    }
    return { data, layout }
  }

  const CONFIG = { responsive: true, displaylogo: false }
  const drawn = new Map()

  function placeholder(element, text) {
    element.innerHTML = ''
    const note = document.createElement('p')
    note.className = 'cx-report__offline'
    note.textContent = text
    element.append(note)
  }

  function draw() {
    const source = document.getElementById('cx-report-figures')
    const figures = source ? JSON.parse(source.textContent) : {}
    for (const element of document.querySelectorAll('[data-figure]')) {
      const figure = figures[element.id]
      if (!figure) {
        placeholder(element, 'Nothing to plot for this run.')
        continue
      }
      if (typeof window.Plotly === 'undefined') {
        placeholder(element, 'This plot needs plotly.js, which the page loads from cdn.plot.ly: open it with an internet connection.')
        continue
      }
      const { data, layout } = styled(figure)
      window.Plotly.newPlot(element, data, layout, { ...CONFIG, toImageButtonOptions: { format: 'svg', filename: element.id } })
      drawn.set(element, figure)
    }
  }

  /** Paint the plots again in the palette now on screen. */
  function repaint() {
    if (typeof window.Plotly === 'undefined') return
    for (const [element, figure] of drawn) {
      const { data, layout } = styled(figure)
      window.Plotly.react(element, data, layout, { ...CONFIG, toImageButtonOptions: { format: 'svg', filename: element.id } })
    }
  }

  window.addEventListener('load', draw)
  new MutationObserver(repaint).observe(document.documentElement, { attributes: true, attributeFilter: ['data-theme'] })
  if (window.matchMedia) window.matchMedia('(prefers-color-scheme: dark)').addEventListener('change', repaint)

  // ---- tables --------------------------------------------------------------

  const rowsOf = (table) => [...table.tBodies[0].rows]
  const shown = (row) => row.style.display !== 'none'
  const valueOf = (cell) => (cell.dataset.sort !== undefined ? cell.dataset.sort : cell.textContent.trim())
  const missing = (text) => text === '' || text === 'NA'
  const asNumber = (text) => (/^[-+]?[\d,]*\.?\d+(e[-+]?\d+)?%?$/i.test(text) ? Number(text.replace(/[,%]/g, '')) : NaN)

  function count(table) {
    const label = document.getElementById(`${table.id}-count`)
    if (!label) return
    const rows = rowsOf(table)
    label.textContent = `${rows.filter(shown).length} of ${rows.length}`
  }

  function filter(table, keep) {
    for (const row of rowsOf(table)) row.style.display = keep(row) ? '' : 'none'
    count(table)
  }

  function sortable(table) {
    const headers = [...table.tHead.rows[0].cells]
    headers.forEach((header, column) => {
      header.tabIndex = 0
      const sort = () => {
        const ascending = header.getAttribute('aria-sort') !== 'ascending'
        for (const other of headers) other.removeAttribute('aria-sort')
        header.setAttribute('aria-sort', ascending ? 'ascending' : 'descending')
        const rows = rowsOf(table).map((row, index) => ({ row, index, text: valueOf(row.cells[column]) }))
        rows.sort((a, b) => {
          // A missing value goes last, whichever way.
          if (missing(a.text) || missing(b.text)) return missing(a.text) - missing(b.text) || a.index - b.index
          const x = asNumber(a.text)
          const y = asNumber(b.text)
          const order = !Number.isNaN(x) && !Number.isNaN(y) ? x - y : a.text.localeCompare(b.text, undefined, { numeric: true })
          return (ascending ? order : -order) || a.index - b.index
        })
        for (const { row } of rows) table.tBodies[0].append(row)
      }
      header.addEventListener('click', sort)
      header.addEventListener('keydown', (event) => {
        if (event.key === 'Enter' || event.key === ' ') {
          event.preventDefault()
          sort()
        }
      })
    })
  }

  function csv(table) {
    const quote = (text) => (/[",\n]/.test(text) ? `"${text.replace(/"/g, '""')}"` : text)
    const cell = (td) => quote(td.dataset.sort !== undefined ? td.dataset.sort : td.textContent.trim())
    const lines = [[...table.tHead.rows[0].cells].map((th) => quote(th.textContent.trim())).join(',')]
    for (const row of rowsOf(table).filter(shown)) lines.push([...row.cells].map(cell).join(','))
    return `${lines.join('\n')}\n`
  }

  ready(() => {
    for (const table of document.querySelectorAll('table[data-sortable]')) {
      sortable(table)
      count(table)
    }

    for (const input of document.querySelectorAll('.cx-report__filter[data-table]')) {
      const table = document.getElementById(input.dataset.table)
      if (!table) continue
      input.addEventListener('input', () => {
        const text = input.value.toLowerCase()
        for (const card of document.querySelectorAll(`[data-filter-table="${input.dataset.table}"]`)) card.setAttribute('aria-pressed', 'false')
        filter(table, (row) => row.textContent.toLowerCase().includes(text))
      })
    }

    for (const button of document.querySelectorAll('.cx-report__download[data-table]')) {
      button.addEventListener('click', () => {
        const table = document.getElementById(button.dataset.table)
        if (!table) return
        const link = document.createElement('a')
        link.href = URL.createObjectURL(new Blob([csv(table)], { type: 'text/csv' }))
        link.download = button.dataset.file || `${table.id}.csv`
        document.body.append(link)
        link.click()
        link.remove()
      })
    }

    for (const card of document.querySelectorAll('[data-filter-table]')) {
      const table = document.getElementById(card.dataset.filterTable)
      if (!table) continue
      card.setAttribute('aria-pressed', 'false')
      const toggle = () => {
        const on = card.getAttribute('aria-pressed') !== 'true'
        for (const other of document.querySelectorAll(`[data-filter-table="${card.dataset.filterTable}"]`)) other.setAttribute('aria-pressed', 'false')
        card.setAttribute('aria-pressed', String(on))
        const input = document.querySelector(`.cx-report__filter[data-table="${table.id}"]`)
        if (input) input.value = ''
        filter(table, (row) => !on || row.dataset.filterValue === card.dataset.filterValue)
        if (on) (table.closest('section') || table).scrollIntoView({ behavior: 'smooth' })
      }
      card.addEventListener('click', toggle)
      card.addEventListener('keydown', (event) => {
        if (event.key === 'Enter' || event.key === ' ') {
          event.preventDefault()
          toggle()
        }
      })
    }

    // The section being read, marked in the bar.
    const links = new Map([...document.querySelectorAll('.cx-report__nav a[href^="#"]')].map((a) => [a.getAttribute('href').slice(1), a]))
    if ('IntersectionObserver' in window && links.size > 0) {
      const visible = new Set()
      const mark = () => {
        const sections = [...links.keys()].map((id) => document.getElementById(id)).filter(Boolean)
        const current = sections.find((section) => visible.has(section.id)) ?? null
        for (const [id, a] of links) {
          if (current && id === current.id) a.setAttribute('aria-current', 'true')
          else a.removeAttribute('aria-current')
        }
      }
      const observer = new IntersectionObserver(
        (entries) => {
          for (const entry of entries) {
            if (entry.isIntersecting) visible.add(entry.target.id)
            else visible.delete(entry.target.id)
          }
          mark()
        },
        { rootMargin: '-80px 0px -55% 0px' },
      )
      for (const id of links.keys()) {
        const section = document.getElementById(id)
        if (section) observer.observe(section)
      }
    }
  })
})()
